-- Schema-only baseline captured read-only before the migration. No business data.
CREATE TABLE public.snp_artisans_miniers (
  id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  type_personne text NOT NULL,
  type_artisan text NOT NULL,
  nom text,
  prenoms text,
  date_naissance date,
  lieu_naissance text,
  sexe text,
  nationalite text DEFAULT 'Malienne'::text,
  raison_sociale text,
  telephone text NOT NULL,
  email text,
  adresse text,
  commune text,
  region text,
  type_piece_identite text,
  numero_piece_identite text,
  date_delivrance_piece date,
  date_expiration_piece date,
  lieu_delivrance_piece text,
  photo_url text,
  piece_identite_url text,
  collecteur_id uuid,
  numero_carte text,
  observations text,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  created_by uuid,
  pays text DEFAULT 'Burkina Faso'::text,
  updated_by uuid,
  telephone_secondaire text,
  numero_registre_commerce text,
  quantite_or_vendu_grammes numeric DEFAULT 0 NOT NULL,
  chiffre_affaires_fcfa numeric DEFAULT 0 NOT NULL,
  nombre_transactions integer DEFAULT 0 NOT NULL,
  derniere_transaction_date date,
  actif boolean DEFAULT true NOT NULL,
  desactive_le timestamp with time zone,
  desactive_par uuid,
  motif_desactivation text,
  artisanal_site_id uuid
);
CREATE TABLE public.snp_artisan_documents (
  id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
  artisan_id uuid NOT NULL,
  type_document text NOT NULL,
  nom_fichier text NOT NULL,
  chemin_fichier text NOT NULL,
  taille_fichier bigint,
  type_mime text,
  description text,
  uploaded_at timestamp with time zone DEFAULT now(),
  uploaded_by uuid
);
ALTER TABLE public.snp_artisans_miniers ADD CONSTRAINT snp_artisans_miniers_type_artisan_check CHECK(type_artisan IN ('exploitant','collecteur','intermediaire','fournisseur'));
ALTER TABLE public.snp_artisan_documents ADD CONSTRAINT snp_artisan_documents_type_document_check CHECK(type_document IN ('photo','cni','passeport','permis','certificat','autre'));
ALTER TABLE public.snp_artisans_miniers ADD CONSTRAINT test_site_fk FOREIGN KEY(artisanal_site_id) REFERENCES public.artisanal_sites(id);
